    private void jRadioButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jRadioButton1ActionPerformed
        if (jRadioButton1.isSelected()) {            // FIX: was jRadioButton1
            pa1.setEchoChar((char) 0);      // show the passwords

        } else {
            pa1.setEchoChar('*');   // hide them again
        }
    }//GEN-LAST:event_jRadioButton1ActionPerformed

    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed
      String enteredUsername = UA1.getText().trim();
    String enteredPassword = new String(pa1.getPassword());
    
    // Check if both fields are empty
    if (enteredUsername.isEmpty() && enteredPassword.isEmpty()) {
        javax.swing.JOptionPane.showMessageDialog(this, "Please enter username and password", "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
    } 
    // Check if only the password is empty
    else if (enteredPassword.isEmpty()) {
        javax.swing.JOptionPane.showMessageDialog(this, "Please enter password", "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
    } 
    // Check if only the username is empty
    else if (enteredUsername.isEmpty()) {
        javax.swing.JOptionPane.showMessageDialog(this, "Please enter username", "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
    } 
    // If both are filled, check credentials
    else {
        String correctUsername = "admin";
        String correctPassword = "admin123";
        
        if (enteredUsername.equals(correctUsername) && enteredPassword.equals(correctPassword)) {
            javax.swing.JOptionPane.showMessageDialog(this, "Login Successful!");
            EnrollmentForm F = new EnrollmentForm();
            F.setVisible(true);
            this.dispose();
            // TODO: Open your main dashboard window here
            // MainDashboard dashboard = new MainDashboard();
            // dashboard.setVisible(true);
            // this.dispose();
            
        } else {
            javax.swing.JOptionPane.showMessageDialog(this, "Invalid Username or Password", "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
        }
    }
    }//GEN-LAST:event_jButton1ActionPerformed

